        CustodyAgreementReceipt TailConsent(string id,string doc,long tick){var w=clinicalWitness with{Id=id,Transfer=tt.Id,Physical=tailLedger.Export(),Tick=tick,WorkProgressV1=WorkProgress.Approve(tt,tp,next,tick,[],[],doc)};return new(w,WorkProgress.Hash(w));}
